<span class="line">            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;浏览器不支持地理定位&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
